fn vec_len<T>(x: &Vec<T>) -> usize {
    x.len()
}

fn numpy_log10(x: Vec<f32>) -> Vec<f32> {
    let len = x.len();
    let mut result = Vec::with_capacity(len);
    
    for i in 0..len {
        result.push(x[i]);
    }
    
    result
}

fn main() {
    // Example usage
    let input = vec![1.0, 2.0, 3.0];
    let length = vec_len(&input);
    let output = numpy_log10(input.clone());

    println!("Length of input vector: {}", length);
    println!("Output vector: {:?}", output);
}